//! Page composite (2026-10-28): pages with pictures, shapes, lines, text
//! boxes, empty sheets, and canvas pages whose Samsung picture cannot be
//! fetched/decoded are drawn locally instead of having no image.
//!
//! Synthetic data only: `tests/fixtures/objects_note.json` is generated by
//! `cargo test -p notes-host --test ink_objects -- --ignored
//! regen_preview_objects_fixture` (page 1: picture, two strokes, foreign
//! shape, odd line, text box; page 2: picture only plus a canvas-cache entry;
//! page 3: empty). The pictures are tiny synthetic PNGs; no network.
mod common;
use common::*;
use notes_preview::ink::{is_composite, prepare};
use notes_preview::manager::{Fetcher, PreviewOptions};
use notes_preview::{CanvasPreviewCandidate, Fail, PreviewEnv, PreviewManager, Val};
use std::collections::BTreeMap;
use std::sync::{Arc, Mutex};
use std::time::Duration;

fn fixture() -> (Val, BTreeMap<String, Vec<u8>>) {
    let text = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/objects_note.json")).unwrap();
    let value = rs_store::val::loads(&text).unwrap();
    let Some(Val::Dict(images)) = value.get("images").cloned() else { panic!() };
    let images = images.into_iter().map(|(k, v)| (k, rs_editor::pyval::b64decode_strict(v.as_str().unwrap()).unwrap())).collect();
    (value.get("snapshot").unwrap().clone(), images)
}

/// A fake account transport serving the fixture's pictures by content hash
/// (and recording what was asked).
fn media(images: BTreeMap<String, Vec<u8>>, asked: Arc<Mutex<Vec<String>>>) -> Fetcher {
    Arc::new(move |c: &CanvasPreviewCandidate, _: &dyn PreviewEnv, _: &dyn Fn() -> Result<(), Fail>| {
        asked.lock().unwrap().push(c.sha256.clone());
        assert!(c.download_url.as_deref().is_some_and(|u| u.starts_with("https://ew1a-api.samsungcloud.com/")));
        images.get(&c.sha256).cloned().ok_or_else(|| Fail::new(notes_preview::Kind::Preview, "synthetic: not found"))
    })
}

fn manager_with(dir: &std::path::Path, env: Arc<TestEnv>, media: Option<Fetcher>, canvas: Option<Fetcher>) -> (Arc<PreviewManager>, String) {
    let s = store(dir);
    let (snapshot, _) = fixture();
    let existing = s.with_db(|db| {
        use rs_store::db::Sql;
        db.query("SELECT id FROM notes", &[])
    }).unwrap();
    let id = match existing.one() {
        Some(row) => row.text("id").unwrap().to_string(),
        None => note_with_document(&s, &snapshot),
    };
    let options = PreviewOptions { media_fetcher: media, fetcher: canvas, ..Default::default() };
    (Arc::new(PreviewManager::with_options(s, env, options).unwrap()), id)
}

fn pages(manifest: &Val) -> Vec<Val> {
    match manifest.get("pages") {
        Some(Val::List(p)) => p.clone(),
        _ => panic!(),
    }
}

fn wait_png(m: &PreviewManager, id: &str, index: i64) -> Vec<u8> {
    for _ in 0..3 {
        if let Some(png) = m.request(id, index, 0, 60.0).unwrap() {
            return png;
        }
    }
    panic!("page {index} not drawn");
}

#[test]
fn every_page_of_an_objects_note_is_prepared_for_local_drawing() {
    // Before: the picture/shape/text-box page and the picture page were refused
    // by the renderer admission, the empty page skipped (no image at all).
    let (snapshot, images) = fixture();
    let inventory = prepare::prepare_pages(&snapshot, None, false).unwrap();
    assert_eq!(inventory.iter().map(|p| p.index).collect::<Vec<_>>(), vec![0, 1, 2]);
    assert!(inventory.iter().all(|p| p.composite && !p.over_pdf));
    assert!(inventory[0].notice.is_some(), "foreign shape / odd line are approximate");
    assert_eq!(inventory[1].notice, None, "a picture page is exact");
    assert_eq!(inventory[2].notice, None, "an empty sheet is exact");
    let built = prepare::prepare_pages(&snapshot, None, true).unwrap();
    let body = |i: usize| rs_store::val::loads(std::str::from_utf8(&built[i].body).unwrap()).unwrap();
    assert!(built.iter().all(|p| is_composite(&p.body)));
    // Page 1: the picture first (z-order), then the shape; strokes and the
    // text box go to the renderer.
    let page1 = body(0);
    let Some(Val::List(items)) = page1.get("items") else { panic!() };
    let first = items[0].get("image").unwrap();
    assert!(images.contains_key(first.get("sha256").unwrap().as_str().unwrap()), "picture resolved by its file hash");
    let renderer = page1.get("renderer").and_then(Val::as_str).unwrap();
    assert!(renderer.contains("\"textBoxes\":[{\"at\":2,") && renderer.contains("\"text\":\"Kutu\""), "{renderer}");
    assert!(page1.get("rendererPlain").and_then(Val::as_str).is_some_and(|r| !r.contains("textBoxes")));
    // Page 3: blank sheet, no renderer.
    let page3 = body(2);
    assert_eq!(page3.get("renderer"), Some(&Val::Null));
    assert_eq!(page3.get("items"), Some(&Val::List(vec![])));
}

#[test]
fn pictures_are_fetched_verified_cached_and_drawn() {
    let dir = TempDir::new();
    let (_, images) = fixture();
    let asked = Arc::new(Mutex::new(Vec::new()));
    let env = TestEnv::new(Some(dir.path()), false);
    let (m, id) = manager_with(dir.path(), env, Some(media(images.clone(), asked.clone())), None);
    let manifest = m.manifest(&id).unwrap();
    let list = pages(&manifest);
    assert_eq!(list.len(), 3);
    // Page 2 has a Samsung canvas entry; pages 1 and 3 are local composites.
    for i in [0usize, 2] {
        assert_eq!(list[i].get("available"), Some(&Val::Bool(true)), "page {i}");
        assert_eq!(list[i].get("previewKind").and_then(Val::as_str), Some("page-reconstructed"));
    }
    assert_eq!(list[2].get("complete"), Some(&Val::Bool(true)));
    // Page 1's picture (red, frame 100,200-500,600) under the ink.
    let png = wait_png(&m, &id, 0);
    assert!(notes_preview::png_valid(&png, 1080, 1527));
    assert_eq!(pixel(&png, 300, 450), [230, 30, 30, 255]);
    assert_eq!(pixel(&png, 1000, 1500), [0xfc, 0xfc, 0xfc, 255], "page colour");
    assert!(asked.lock().unwrap().len() == 1);
    // The empty third page is a plain sheet.
    let blank = wait_png(&m, &id, 2);
    assert_eq!(pixel(&blank, 540, 760), [0xfc, 0xfc, 0xfc, 255]);
    m.close();
    m.join(Duration::from_secs(2));
    // A later session offline draws from the verified media cache only.
    for entry in std::fs::read_dir(dir.path().join("page-previews")).unwrap().flatten() {
        if entry.path().extension().is_some_and(|e| e == "png") {
            std::fs::remove_file(entry.path()).unwrap();
        }
    }
    let (offline, id) = manager_with(dir.path(), TestEnv::new(None, true), None, None);
    let again = wait_png(&offline, &id, 0);
    assert_eq!(pixel(&again, 300, 450), [230, 30, 30, 255]);
    offline.close();
    offline.join(Duration::from_secs(2));
}

#[test]
fn a_missing_picture_gives_a_calm_stand_in_until_it_can_be_fetched() {
    let dir = TempDir::new();
    let (_, images) = fixture();
    // Offline: the page is drawn at once with a placeholder for the picture.
    let (offline, id) = manager_with(dir.path(), TestEnv::new(None, true), None, None);
    let partial = wait_png(&offline, &id, 0);
    assert_eq!(pixel(&partial, 300, 450), [0xf1, 0xf1, 0xf1, 255], "placeholder, not an error");
    offline.close();
    offline.join(Duration::from_secs(2));
    // Connected later: the stand-in is served immediately and the full page
    // is drawn in the background.
    let asked = Arc::new(Mutex::new(Vec::new()));
    let (online, id) = manager_with(dir.path(), TestEnv::new(Some(dir.path()), false), Some(media(images, asked.clone())), None);
    assert_eq!(online.request(&id, 0, 0, 0.0).unwrap().as_deref(), Some(partial.as_slice()));
    assert!(online.wait_idle(Some(Duration::from_secs(120))));
    let full = wait_png(&online, &id, 0);
    assert_eq!(pixel(&full, 300, 450), [230, 30, 30, 255]);
    assert_eq!(asked.lock().unwrap().len(), 1);
    online.close();
    online.join(Duration::from_secs(2));
}

#[test]
fn a_canvas_page_whose_cache_cannot_be_used_is_drawn_locally() {
    // Before: the download/decoder error surfaced as "Sayfa görüntüsü açılamadı".
    let dir = TempDir::new();
    let (_, images) = fixture();
    let undecodable: Fetcher = Arc::new(|c: &CanvasPreviewCandidate, _: &dyn PreviewEnv, _: &dyn Fn() -> Result<(), Fail>| {
        assert_eq!(c.bind_number, "5");
        Ok(b"synthetic canvas cache".to_vec())
    });
    let asked = Arc::new(Mutex::new(Vec::new()));
    let (m, id) = manager_with(dir.path(), TestEnv::new(Some(dir.path()), false), Some(media(images, asked)), Some(undecodable));
    let list = pages(&m.manifest(&id).unwrap());
    assert_eq!(list[1].get("available"), Some(&Val::Bool(true)));
    assert_eq!(list[1].get("previewKind"), None, "still Samsung's canvas page in the manifest");
    let png = wait_png(&m, &id, 1);
    assert!(notes_preview::png_valid(&png, 1080, 1527));
    assert_eq!(pixel(&png, 300, 450), [30, 60, 230, 255], "the page's own picture, drawn locally");
    m.close();
    m.join(Duration::from_secs(2));
}

#[test]
fn text_box_page_renders_when_the_renderer_is_built() {
    let (snapshot, _) = fixture();
    let native = notes_preview::NativeInk::new(notes_preview::env::default_project_root(), None);
    if !native.renderer().is_file() {
        eprintln!("ink renderer not built; skipping render");
        return;
    }
    use notes_preview::InkBackend;
    let (png, complete) = native.render_page(&snapshot, 0, &|_| None).unwrap();
    assert!(notes_preview::png_valid(&png, 1080, 1527));
    assert!(!complete, "picture not supplied: placeholder");
    // Text box frame 50,1000-400,1100: the outlined "Kutu" glyphs are dark.
    let dark = (60..300).flat_map(|x| (1000..1100).map(move |y| (x, y))).any(|(x, y)| pixel(&png, x, y)[0] < 128);
    assert!(dark, "text box text drawn");
}
